package com.yeyamo_mobile.api.notification_service.domain;
import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;
class NotificationDomainTest{@Test void emailRequiresAddress(){assertThrows(IllegalArgumentException.class,()->new NotificationPreference("u1",true,true,false,null,null,"fr",Instant.now()));}@Test void pushRequiresToken(){assertThrows(IllegalArgumentException.class,()->new NotificationPreference("u1",true,false,true,null,null,"fr",Instant.now()));}@Test void computesExponentialRetry(){Delivery d=new Delivery(UUID.randomUUID(),UUID.randomUUID(),NotificationChannel.EMAIL,"a@test.io",DeliveryStatus.PENDING,0,Instant.now(),null,null);Delivery retry=d.failed("smtp unavailable",Instant.parse("2026-01-01T00:00:00Z"),5,30);assertEquals(DeliveryStatus.RETRY,retry.status());assertEquals(1,retry.attempts());assertEquals(Instant.parse("2026-01-01T00:00:30Z"),retry.nextAttemptAt());}@Test void deadLettersAtMaximumAttempts(){Delivery d=new Delivery(UUID.randomUUID(),UUID.randomUUID(),NotificationChannel.PUSH,"token",DeliveryStatus.RETRY,4,Instant.now(),null,null);assertEquals(DeliveryStatus.DEAD_LETTER,d.failed("down",Instant.now(),5,30).status());}}
